import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Weapons and Damage Types","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/weapons-and-damage.md","filePath":"en/guide/combat/weapons-and-damage.md"}'),o={name:"en/guide/combat/weapons-and-damage.md"};function i(n,t,l,s,h,m){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="weapons-and-damage-types" tabindex="-1">Weapons and Damage Types <a class="header-anchor" href="#weapons-and-damage-types" aria-label="Permalink to &quot;Weapons and Damage Types&quot;">​</a></h1><p><strong>Status:</strong> Proposed weapon identities · Experimental numbers · Accepted health/trauma separation.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Sword, spear and hammer create different spacing, tempo and stamina problems.</li><li>Global damage and Local Trauma are distinct; quality does not erase weapon trade-offs.</li><li>Listed numbers are Experimental test values, not live balance.</li></ul><p>Weapons should create different tactical problems. Craft quality helps a weapon perform its role; it does not erase its trade-offs.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Weapon</th><th>Reach</th><th>Tempo</th><th>Stamina</th><th>Trauma emphasis</th><th>Strength</th><th>Trade-off</th></tr></thead><tbody><tr><td>Longsword</td><td>1</td><td>Medium</td><td>Medium</td><td>Cutting / piercing</td><td>Duel control</td><td>Limited reach</td></tr><tr><td>Spear</td><td>2; Lunge 3</td><td>Medium</td><td>Medium–high</td><td>Piercing</td><td>Spacing</td><td>Weak up close</td></tr><tr><td>War Hammer</td><td>1; Arc 2</td><td>Slow</td><td>High</td><td>Blunt</td><td>Commitment punish</td><td>Costly miss</td></tr></tbody></table><p>Numbers belong to the Experimental three-weapon profile. Trauma descriptions are identities, not new fracture, bleeding or penetration formulas.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td>Global damage</td><td>Reduces overall health</td></tr><tr><td>Local Trauma</td><td>Affects the actual body region; separate from health</td></tr><tr><td>Quality</td><td>Materials, technique, consistency and handling</td></tr><tr><td>Protection</td><td>Armor and shields interact with the actual attack</td></tr></tbody></table><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><ul><li>A heavy hit must not make hammer the universal highest-DPS choice.</li><li>Sword versatility competes with spear distance and hammer commitment.</li><li>Axes and daggers retain proposed identities; bows receive no numeric kit in this batch.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A missed Heavy Blow leaves more recovery to punish than a Basic Slash. A larger relative impact does not guarantee a better outcome.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/numeric-prototype.html">Three-weapon action tables</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/guide/combat/armor-and-protection.html">Armor</a> · <a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">Full specification</a></p><p><span id="choose-a-way-to-fight"></span><span id="read-the-encounter"></span></p>',17)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
